#include "partial-tree-proof.h"
#include "test_support.h"
#include <stdexcept>
int main(){using namespace partial_tree;std::vector<std::string> l={"a","b","c","d","e"};auto expected=root(l);for(auto s:std::vector<std::vector<std::size_t>>{{},{0},{4},{0,2,4},{0,1,2,3,4}}){auto p=build(l,s);std::vector<std::pair<std::size_t,std::string>> m;for(auto i:s)m.push_back({i,l[i]});CHECK(verify(l.size(),m,p,expected));if(!m.empty()){m[0].second+="x";CHECK(!verify(l.size(),m,p,expected));}}auto odd_expected=hash_pair(hash_pair(hash_pair(hash_leaf("a"),hash_leaf("b")),hash_pair(hash_leaf("c"),hash_leaf("d"))),hash_pair(hash_pair(hash_leaf("e"),hash_leaf("e")),hash_pair(hash_leaf("e"),hash_leaf("e"))));CHECK(expected==odd_expected);auto p=build(l,{2});p.hashes.push_back(99);CHECK(!verify(5,{{2,"c"}},p,expected));p=build(l,{2});p.flags.push_back(false);CHECK(!verify(5,{{2,"c"}},p,expected));CHECK_THROWS(std::invalid_argument,root({}));CHECK_THROWS(std::invalid_argument,build(l,{2,2}));CHECK(!verify(0,{},{{false},{1}},1));return charm_failures?1:0;}
